import{_ as e,o as a,c as o,a4 as d}from"./chunks/framework.WdFb_vN1.js";const p=JSON.parse('{"title":"Header slots","description":"","frontmatter":{},"headers":[],"relativePath":"draggable/header-slots.md","filePath":"draggable/header-slots.md","lastUpdated":1789487288000}'),r={name:"draggable/header-slots.md"};function l(s,t,i,n,c,h){return a(),o("div",null,t[0]||(t[0]=[d('<h1 id="header-slots" tabindex="-1">Header slots <a class="header-anchor" href="#header-slots" aria-label="Permalink to &quot;Header slots&quot;">​</a></h1><p>Stable header chrome layout for draggable item shells (popup, modal, drawer, float, sidebar, bottom). Documented slot / prop names are <strong>Stable</strong> — renaming them is a <strong>major</strong>.</p><p>Related: <a href="./stable-api.html">Stable API</a> · <a href="./">Docs hub</a></p><h2 id="layout" tabindex="-1">Layout <a class="header-anchor" href="#layout" aria-label="Permalink to &quot;Layout&quot;">​</a></h2><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>[ pre-title ] [ title | after-title ] …… spacer …… [ extra-btn ]</span></span></code></pre></div><ul><li><strong>pre-title</strong> — left of the title group (e.g. back / drag handle host).</li><li><strong>title</strong> — plain string for switcher/store (<code>title</code> prop) and/or custom node (<code>#title</code> / <code>titleNode</code> on sidebar).</li><li><strong>after-title</strong> — immediately to the <strong>right</strong> of the title (same title group), before the spacer.</li><li><strong>extra-btn</strong> — trailing actions after the spacer (close / expand / custom buttons).</li></ul><p><code>DragHeader</code> (internal) implements this layout; public item components forward the same names.</p><h2 id="vue-↔-react-names" tabindex="-1">Vue ↔ React names <a class="header-anchor" href="#vue-↔-react-names" aria-label="Permalink to &quot;Vue ↔ React names&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Vue slot</th><th>React prop / node</th><th>Role</th></tr></thead><tbody><tr><td><code>pre-title</code></td><td><code>preTitle</code></td><td>Before the title group</td></tr><tr><td><code>title</code> (prop)</td><td><code>title</code></td><td>Plain string (switcher menu + default header)</td></tr><tr><td><code>title</code> (slot)</td><td><code>titleNode</code></td><td>Custom header title node (sidebar); falls back to <code>title</code></td></tr><tr><td><code>after-title</code></td><td><code>afterTitle</code></td><td>Immediately after title, before spacer</td></tr><tr><td><code>extra-btn</code></td><td><code>extraBtn</code></td><td>Trailing header actions after the spacer</td></tr><tr><td><code>default</code></td><td><code>children</code></td><td>Panel body (not part of the header row)</td></tr></tbody></table><h2 id="rules" tabindex="-1">Rules <a class="header-anchor" href="#rules" aria-label="Permalink to &quot;Rules&quot;">​</a></h2><ol><li>Hosts that place actions “in the title” (e.g. menu <code>location: &#39;title&#39;</code>) must map those into the <strong><code>after-title</code> / <code>afterTitle</code></strong> slot — <strong>not</strong> <code>extra-btn</code>.</li><li>React sidebar: use <strong><code>title</code></strong> (string) for the switcher store label; use <strong><code>titleNode</code></strong> for a custom header node (Vue <code>#title</code> slot). Other shells may still pass a display <code>title</code> node where noted.</li><li>When the visible header differs from the switcher label, set both a plain <code>title</code> string and a styled <code>#title</code> / <code>titleNode</code>.</li><li>Do not place trailing chrome (close, expand, switcher) in <code>after-title</code>; those belong in <code>extra-btn</code> / built-in header actions.</li><li>Not every shell exposes every slot (e.g. some omit <code>pre-title</code>). Names that <em>are</em> documented on a component remain Stable for that surface.</li></ol><h2 id="component-docs" tabindex="-1">Component docs <a class="header-anchor" href="#component-docs" aria-label="Permalink to &quot;Component docs&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Component</th><th>Doc</th></tr></thead><tbody><tr><td>Popup</td><td><a href="./draggable-item-popup.html">draggable-item-popup.md</a></td></tr><tr><td>Modal</td><td><a href="./draggable-modal.html">draggable-modal.md</a></td></tr><tr><td>Drawer</td><td><a href="./draggable-drawer.html">draggable-drawer.md</a></td></tr><tr><td>Float</td><td><a href="./draggable-item-float.html">draggable-item-float.md</a></td></tr><tr><td>Sidebar</td><td><a href="./draggable-item-sidebar.html">draggable-item-sidebar.md</a></td></tr><tr><td>Bottom</td><td><a href="./draggable-item-bottom.html">draggable-item-bottom.md</a></td></tr></tbody></table>',13)]))}const g=e(r,[["render",l]]);export{p as __pageData,g as default};
